#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""万感京张 OSM 肌理读数包 —— 复算脚本。

输入：
  osm-fabric-snapshot.json                                （本目录，OSM 精简快照）
  <submission>/geometry/site_boundary.geojson             （场地边界）
  <submission>/geometry/roads.geojson                     （五条慢行中心线）
  <submission>/geometry/constraints.geojson               （十个独立完成节点）

输出：
  osm-fabric-readings.json                                （全部读数）

依赖：shapely >= 2.0，pyproj >= 3.0（其余为 Python 标准库）。
用法：python3 compute_fabric.py [--submission <提交包路径>]

全部平面量算在 EPSG:4548（CGCS2000 / 3-degree Gauss-Kruger CM 117E）下进行。
本脚本为确定性计算：同一快照与同一提交几何重复执行，输出逐字节一致。

数据版权：© OpenStreetMap contributors，ODbL 1.0。
"""

import argparse
import hashlib
import json
import math
import os
import statistics
import sys

from pyproj import Transformer
from shapely.geometry import LineString, Point, shape
from shapely.ops import polygonize, transform, unary_union
from shapely.strtree import STRtree

HERE = os.path.dirname(os.path.abspath(__file__))
DEFAULT_SUBMISSION = "/Users/tutu/Projects/Haidian_Open_City/submissions/lqqk7/every-sense-jingzhang"

SNAPSHOT = os.path.join(HERE, "osm-fabric-snapshot.json")
OUT = os.path.join(HERE, "osm-fabric-readings.json")

PROJ_CRS = "EPSG:4548"

# ---------------------------------------------------------------- 口径定义 ---

# 可步行网络：排除机动车专用高等级道路及其匝道、排除未建成与非通行线要素。
# 排除项逐项理由见读数文件 method 字段。
WALKABLE_EXCLUDED_HIGHWAY = {
    "motorway", "motorway_link",   # 机动车专用，禁止步行
    "trunk", "trunk_link",         # 机动车专用高等级，本区段为高架/封闭断面
    "construction",                # 未建成
    "proposed",                    # 未建成
    "platform",                    # 站台，非通行线要素
    "elevator",                    # 垂直交通点要素，非水平网络
    "raceway", "bus_guideway", "escape",
}

# 步行专用要素：OSM 中以步行（含人非共板）为主导用途的类型，作为偏差读数的次口径。
PEDESTRIAN_DEDICATED_HIGHWAY = {
    "footway", "path", "steps", "pedestrian", "cycleway",
}

# 超大封闭街块阈值（方法选择，非规范强制值）。
OVERSIZED_BLOCK_THRESHOLD_M2 = 40000.0

# 交叉口聚类半径。
INTERSECTION_CLUSTER_RADIUS_M = 15.0

# 中心线采样间距。
CENTERLINE_SAMPLE_INTERVAL_M = 25.0

# 穿越点判定：交点邻域内检索过街节点的半径。
CROSSING_NODE_SEARCH_RADIUS_M = 10.0

# 穿越点判定：与屏障的夹角下限，低于此值视为贴边平行而非横穿。
CROSSING_MIN_ANGLE_DEG = 30.0

# 跨轨道穿越的位置聚类半径：把同一处穿越的多条 way 记录合并为一个位置。
RAIL_CROSSING_CLUSTER_RADIUS_M = 50.0

# 屏障定义。匝道（*_link）不计入屏障主集合：匝道是立交的组成部分而非独立
# 屏障，纳入会把同一处立交拆成多条记录。为便于换口径复算，匝道口径下的
# 记录数一并登记在清单 counts 中。
RAIL_BARRIER_RAILWAY = {"rail"}                 # 在营地面轨道
RAIL_HERITAGE_RAILWAY = {"disused", "razed"}    # 停用/拆除轨道（京张遗址线）
ROAD_BARRIER_HIGHWAY = {"motorway", "trunk"}
ROAD_BARRIER_LINK_HIGHWAY = {"motorway_link", "trunk_link"}

# 主证据：OpenStreetMap 中直接表达穿越设施的要素标签。
PRIMARY_EVIDENCE_KINDS = {
    "bridge", "tunnel", "level_crossing", "railway_crossing_node", "crossing_node",
}

# 数据质量分段数（沿场地纵向等分）。
QUALITY_SEGMENTS = 10

BRIDGE_VALUES = {"yes", "viaduct", "covered", "boardwalk"}
TUNNEL_VALUES = {"yes", "building_passage", "culvert"}


def r3(v):
    """全部读数统一保留三位小数登记。"""
    if v is None:
        return None
    if isinstance(v, float) and (math.isnan(v) or math.isinf(v)):
        return None
    return round(float(v), 3)


# ------------------------------------------------------------------ 载入 ---

def load_snapshot():
    with open(SNAPSHOT, "rb") as f:
        raw = f.read()
    sha = hashlib.sha256(raw).hexdigest()
    data = json.loads(raw.decode("utf-8"))
    return data, sha, len(raw)


def load_submission(sub):
    def rd(name):
        with open(os.path.join(sub, "geometry", name), "r", encoding="utf-8") as f:
            return json.load(f)
    return rd("site_boundary.geojson"), rd("roads.geojson"), rd("constraints.geojson")


# -------------------------------------------------------------- 几何准备 ---

class Fabric(object):
    def __init__(self, snapshot, site_geojson):
        self.meta = snapshot["meta"]
        self.tr = Transformer.from_crs("EPSG:4326", PROJ_CRS, always_xy=True)
        self._proj = lambda x, y: self.tr.transform(x, y)

        site_wgs = shape(site_geojson["features"][0]["geometry"])
        wb = site_wgs.bounds
        self.site_bounds_wgs84 = [round(v, 6) for v in wb]
        self.site_bounds_lat = (wb[1], wb[3])
        self.site = transform(self._proj, site_wgs)
        self.site_area_m2 = self.site.area
        self.site_area_km2 = self.site_area_m2 / 1e6

        # way 记录：(osm_id, highway, railway, name, tags, coords)
        self.ways = snapshot["ways"]
        self.nodes = snapshot["nodes"]

        self.walkable = []          # 可步行网络 way 索引
        self.pedestrian = []        # 步行专用要素 way 索引
        self.rail_active = []
        self.rail_heritage = []
        self.road_barrier = []
        self.road_barrier_link = []
        for i, w in enumerate(self.ways):
            hw, rw = w[1], w[2]
            if hw and hw not in WALKABLE_EXCLUDED_HIGHWAY:
                self.walkable.append(i)
                if hw in PEDESTRIAN_DEDICATED_HIGHWAY:
                    self.pedestrian.append(i)
            if hw in ROAD_BARRIER_HIGHWAY:
                self.road_barrier.append(i)
            elif hw in ROAD_BARRIER_LINK_HIGHWAY:
                self.road_barrier_link.append(i)
            if rw in RAIL_BARRIER_RAILWAY:
                self.rail_active.append(i)
            elif rw in RAIL_HERITAGE_RAILWAY:
                self.rail_heritage.append(i)

        self.inv = Transformer.from_crs(PROJ_CRS, "EPSG:4326", always_xy=True)
        self._plines = {}

    def unproj(self, x, y):
        return self.inv.transform(x, y)

    def pline(self, i):
        """way 的投影后 LineString（缓存）。"""
        if i not in self._plines:
            cs = self.ways[i][5]
            pts = [self._proj(x, y) for x, y in cs]
            ded = [pts[0]]
            for p in pts[1:]:
                if p != ded[-1]:
                    ded.append(p)
            self._plines[i] = LineString(ded) if len(ded) >= 2 else None
        return self._plines[i]

    def tags(self, i):
        return self.ways[i][4] or {}


# ----------------------------------------------------- 读数 1 路网密度 ---

def reading_network_density(fb):
    total_len = 0.0
    used = 0
    clipped = 0
    private_len = 0.0
    private_cnt = 0
    for i in fb.walkable:
        ln = fb.pline(i)
        if ln is None:
            continue
        used += 1
        inter = ln.intersection(fb.site)
        if inter.is_empty:
            continue
        clipped += 1
        L = inter.length
        total_len += L
        t = fb.tags(i)
        if t.get("access") == "private" or t.get("foot") == "no":
            private_len += L
            private_cnt += 1
    km = total_len / 1000.0
    return {
        "value": r3(km / fb.site_area_km2),
        "total_length_m": r3(total_len),
        "walkable_ways_total": used,
        "walkable_ways_intersecting_site": clipped,
        "restricted_access_length_m": r3(private_len),
        "restricted_access_ways": private_cnt,
    }


# --------------------------------------------- 图构造（交叉口与街块共用）---

def build_graph(fb):
    """按 OpenStreetMap 拓扑构造平面图：以共享顶点为连接依据。

    立体交叉在 OpenStreetMap 中不共享顶点，因此本图不会把桥下穿或
    隧道穿误判为平面交叉口，也不会据此闭合虚假街块。
    """
    adj = {}
    edges = set()
    for i in sorted(fb.walkable):
        cs = fb.ways[i][5]
        prev = None
        for x, y in cs:
            k = (x, y)
            if k not in adj:
                adj[k] = set()
            if prev is not None and prev != k:
                adj[prev].add(k)
                adj[k].add(prev)
                edges.add((prev, k) if prev < k else (k, prev))
            prev = k
    return adj, edges


def cluster_points(pts, radius):
    """单链聚类（网格索引 + 并查集），返回 (簇数, 被合并的点数)。

    任意两点距离不超过 radius 即归入同一簇，簇内传递合并。
    输入先行排序，结果不依赖输入顺序。
    """
    cand = sorted(pts)
    R = float(radius)
    grid = {}
    for idx, (x, y) in enumerate(cand):
        grid.setdefault((int(math.floor(x / R)), int(math.floor(y / R))), []).append(idx)
    parent = list(range(len(cand)))

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    for (gx, gy) in sorted(grid):
        for idx in grid[(gx, gy)]:
            x0, y0 = cand[idx]
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    for jdx in grid.get((gx + dx, gy + dy), ()):
                        if jdx <= idx:
                            continue
                        x1, y1 = cand[jdx]
                        if (x1 - x0) ** 2 + (y1 - y0) ** 2 <= R * R:
                            union(idx, jdx)
    clusters = len({find(i) for i in range(len(cand))})
    return clusters, len(cand) - clusters


def reading_intersection_density(fb, adj):
    cand = []
    for k in sorted(adj):
        if len(adj[k]) >= 3:
            px, py = fb._proj(k[0], k[1])
            if fb.site.contains(Point(px, py)):
                cand.append((px, py))
    clusters, merged = cluster_points(cand, INTERSECTION_CLUSTER_RADIUS_M)
    return {
        "value": r3(clusters / fb.site_area_km2),
        "intersection_count": clusters,
        "degree3_vertices_in_site": len(cand),
        "vertices_merged_by_clustering": merged,
        "graph_vertices_total": len(adj),
        "graph_edges_total": None,  # 由调用方填入
    }


def reading_blocks(fb, edges):
    segs = []
    for a, b in sorted(edges):
        pa = fb._proj(a[0], a[1])
        pb = fb._proj(b[0], b[1])
        if pa != pb:
            segs.append(LineString([pa, pb]))
    polys = list(polygonize(segs))
    inside = []
    for p in polys:
        if p.area <= 0:
            continue
        if fb.site.contains(p.representative_point()):
            inside.append(p)
    areas = sorted(p.area for p in inside)
    if not areas:
        return None, []
    total = sum(areas)

    # 重叠自检：本包刻意不做几何 noding（以保护立交语义），因此嵌套环
    # 与不同分层各自成环处会在平面上产生少量重叠。此处如实量化。
    ov_pairs = 0
    ov_area = 0.0
    if inside:
        tree = STRtree(inside)
        for i, p in enumerate(inside):
            for j in tree.query(p):
                if j <= i:
                    continue
                it = p.intersection(inside[j])
                if it.area > 1e-6:
                    ov_pairs += 1
                    ov_area += it.area
    over = [a for a in areas if a > OVERSIZED_BLOCK_THRESHOLD_M2]
    ref = [a for a in areas if a >= 1000.0]
    return {
        "median_all_m2": r3(statistics.median(areas)),
        "median_ge_1000_m2": r3(statistics.median(ref)) if ref else None,
        "block_count": len(areas),
        "block_count_ge_1000_m2": len(ref),
        "block_count_lt_500_m2": len([a for a in areas if a < 500.0]),
        "total_block_area_m2": r3(total),
        "oversized_count": len(over),
        "oversized_area_m2": r3(sum(over)),
        "oversized_share_pct": r3(100.0 * sum(over) / total),
        "polygonized_total": len(polys),
        "largest_block_m2": r3(areas[-1]),
        "smallest_block_m2": r3(areas[0]),
        "overlapping_face_pairs": ov_pairs,
        "overlap_area_m2": r3(ov_area),
        "overlap_share_of_total_pct": r3(100.0 * ov_area / total),
    }, areas


# ---------------------------------------------------------- 偏差读数工具 ---

def make_tree(fb, idxs):
    geoms = []
    for i in sorted(idxs):
        ln = fb.pline(i)
        if ln is not None:
            geoms.append(ln)
    return STRtree(geoms), geoms


def nearest_dist(tree, geoms, pt):
    j = tree.nearest(pt)
    return pt.distance(geoms[j])


def sample_line(ln, step):
    n = max(1, int(math.floor(ln.length / step)))
    ds = [k * step for k in range(n + 1)]
    if ds[-1] < ln.length - 1e-9:
        ds.append(ln.length)
    return [ln.interpolate(d) for d in ds]


def dist_stats(ds):
    ds = sorted(ds)
    n = len(ds)
    if n == 0:
        return {}
    def pct(p):
        if n == 1:
            return ds[0]
        pos = p * (n - 1)
        lo = int(math.floor(pos))
        hi = min(lo + 1, n - 1)
        return ds[lo] + (ds[hi] - ds[lo]) * (pos - lo)
    return {
        "median_m": r3(statistics.median(ds)),
        "p90_m": r3(pct(0.90)),
        "max_m": r3(ds[-1]),
        "min_m": r3(ds[0]),
        "mean_m": r3(sum(ds) / n),
        "sample_count": n,
    }


# ---------------------------------------------------------- 穿越点判定 ---

def bearing_deg(p0, p1):
    """正北为 0，顺时针，归一化到 [0,180)。"""
    dx = p1[0] - p0[0]
    dy = p1[1] - p0[1]
    a = math.degrees(math.atan2(dx, dy)) % 180.0
    return a


def local_bearing(ln, pt, window=20.0):
    d = ln.project(pt)
    a = ln.interpolate(max(0.0, d - window))
    b = ln.interpolate(min(ln.length, d + window))
    if a.equals(b):
        return None
    return bearing_deg((a.x, a.y), (b.x, b.y))


def angle_between(b1, b2):
    if b1 is None or b2 is None:
        return None
    d = abs(b1 - b2) % 180.0
    return min(d, 180.0 - d)


def collect_crossings(fb, node_tree, node_geoms, node_recs, include_links=False):
    """沿走廊全长登记可步行要素与屏障的全部相交点，并逐点分级。"""
    barriers = []
    for i in fb.rail_active:
        barriers.append((i, "rail_active"))
    for i in fb.rail_heritage:
        barriers.append((i, "rail_heritage"))
    for i in fb.road_barrier:
        barriers.append((i, "road_barrier"))
    if include_links:
        for i in fb.road_barrier_link:
            barriers.append((i, "road_barrier_link"))

    bgeoms = []
    bidx = []
    for i, kind in barriers:
        ln = fb.pline(i)
        if ln is not None:
            bgeoms.append(ln)
            bidx.append((i, kind))
    btree = STRtree(bgeoms)

    # 屏障顶点集合，用于判定共享节点（平交道口）。
    bverts = {}
    for i, kind in barriers:
        for x, y in fb.ways[i][5]:
            bverts.setdefault((x, y), []).append(i)

    out = []
    seen = set()
    for wi in sorted(fb.walkable):
        wl = fb.pline(wi)
        if wl is None:
            continue
        for j in btree.query(wl):
            bg = bgeoms[j]
            bi, bkind = bidx[j]
            if not wl.intersects(bg):
                continue
            inter = wl.intersection(bg)
            pts = []
            gt = inter.geom_type
            if gt == "Point":
                pts = [inter]
            elif gt == "MultiPoint":
                pts = list(inter.geoms)
            elif gt in ("LineString", "MultiLineString", "GeometryCollection"):
                # 重合段：取代表点，并登记为重合（通常是并行贴边或数据缺陷）。
                rp = inter.representative_point()
                pts = [rp]
            for p in pts:
                key = (wi, bi, round(p.x, 2), round(p.y, 2))
                if key in seen:
                    continue
                seen.add(key)

                wb = local_bearing(wl, p)
                bb = local_bearing(bg, p)
                ang = angle_between(wb, bb)
                if ang is not None and ang < CROSSING_MIN_ANGLE_DEG:
                    continue  # 贴边平行，不是横穿

                wt = fb.tags(wi)
                bt = fb.tags(bi)
                ev = None
                kinds = []
                if wt.get("bridge") in BRIDGE_VALUES:
                    kinds.append("bridge")
                if wt.get("tunnel") in TUNNEL_VALUES:
                    kinds.append("tunnel")

                # 共享顶点 → 平面相接。检索该顶点是否为登记的道口节点。
                shared = None
                for x, y in fb.ways[wi][5]:
                    if (x, y) in bverts and bi in bverts[(x, y)]:
                        px, py = fb._proj(x, y)
                        if (px - p.x) ** 2 + (py - p.y) ** 2 < 1.0:
                            shared = (x, y)
                            break

                near_nodes = []
                pp = Point(p.x, p.y)
                for k in node_tree.query(pp.buffer(CROSSING_NODE_SEARCH_RADIUS_M)):
                    if pp.distance(node_geoms[k]) <= CROSSING_NODE_SEARCH_RADIUS_M:
                        near_nodes.append(node_recs[k])
                lc = [n for n in near_nodes if n[3] == "railway=level_crossing"]
                rc = [n for n in near_nodes if n[3] == "railway=crossing"]
                hc = [n for n in near_nodes if n[3] == "highway=crossing"]
                if lc:
                    kinds.append("level_crossing")
                if rc:
                    kinds.append("railway_crossing_node")
                if hc and bkind.startswith("road_barrier"):
                    kinds.append("crossing_node")

                if not kinds:
                    try:
                        wlayer = int(wt.get("layer", "0"))
                    except ValueError:
                        wlayer = 0
                    try:
                        blayer = int(bt.get("layer", "0"))
                    except ValueError:
                        blayer = 0
                    if wlayer != blayer:
                        kinds.append("layer_separation")

                kinds = sorted(set(kinds))
                grade = "evidence_present" if kinds else "no_evidence_registered_only"
                if not kinds:
                    tier = None
                elif set(kinds) & PRIMARY_EVIDENCE_KINDS:
                    tier = "primary"
                else:
                    tier = "secondary"
                # 反算经纬度用于登记（保持与快照同精度）。
                lon, lat = fb.unproj(p.x, p.y)

                out.append({
                    "crossing_way_osm_id": fb.ways[wi][0],
                    "crossing_way_highway": fb.ways[wi][1],
                    "crossing_way_name": fb.ways[wi][3],
                    "barrier_osm_id": fb.ways[bi][0],
                    "barrier_kind": bkind,
                    "barrier_railway": fb.ways[bi][2],
                    "barrier_highway": fb.ways[bi][1],
                    "barrier_name": fb.ways[bi][3],
                    "lon": round(lon, 6),
                    "lat": round(lat, 6),
                    "crossing_bearing_deg": r3(wb),
                    "barrier_bearing_deg": r3(bb),
                    "angle_to_barrier_deg": r3(ang),
                    "east_west_dominant": (wb is not None and abs(wb - 90.0) <= 45.0),
                    "shares_vertex_with_barrier": shared is not None,
                    "evidence_kinds": kinds,
                    "evidence_tier": tier,
                    "grade": grade,
                    "in_site": fb.site.contains(pp),
                    "level_crossing_node_osm_ids": sorted(n[0] for n in lc),
                    "crossing_node_osm_ids": sorted(n[0] for n in (rc + hc)),
                })
    out.sort(key=lambda d: (d["lat"], d["lon"], d["crossing_way_osm_id"]))
    return out


# ------------------------------------------------------- 数据质量分段读数 ---

def segment_quality(fb):
    """把场地沿纵向等分为若干段，逐段量测步行细部数据的覆盖程度。

    用途：定位快照中步行数据明显缺失的区段，作为全部读数的判读前提。
    """
    from shapely.geometry import box
    minx, miny, maxx, maxy = fb.site.bounds
    step = (maxy - miny) / QUALITY_SEGMENTS
    segs = []
    for k in range(QUALITY_SEGMENTS):
        y0 = miny + k * step
        y1 = miny + (k + 1) * step
        cell = fb.site.intersection(box(minx - 10.0, y0, maxx + 10.0, y1))
        if cell.is_empty or cell.area <= 0:
            continue
        wlen = 0.0
        plen = 0.0
        for i in fb.walkable:
            ln = fb.pline(i)
            if ln is None:
                continue
            it = ln.intersection(cell)
            if it.is_empty:
                continue
            wlen += it.length
            if fb.ways[i][1] in PEDESTRIAN_DEDICATED_HIGHWAY:
                plen += it.length
        akm2 = cell.area / 1e6
        c = cell.representative_point()
        lon0, lat0 = fb.unproj(c.x, c.y)
        lo_lon, lo_lat = fb.unproj(minx, y0)
        hi_lon, hi_lat = fb.unproj(minx, y1)
        segs.append({
            "segment": k + 1,
            "lat_range": [round(lo_lat, 6), round(hi_lat, 6)],
            "area_km2": r3(akm2),
            "walkable_length_m": r3(wlen),
            "walkable_density_km_per_km2": r3((wlen / 1000.0) / akm2) if akm2 else None,
            "pedestrian_dedicated_length_m": r3(plen),
            "pedestrian_dedicated_share_pct": r3(100.0 * plen / wlen) if wlen else None,
        })
    shares = [s["pedestrian_dedicated_share_pct"] for s in segs
              if s["pedestrian_dedicated_share_pct"] is not None]
    med = statistics.median(shares) if shares else None
    for s in segs:
        sh = s["pedestrian_dedicated_share_pct"]
        s["flag"] = ("pedestrian_detail_sparse"
                     if (sh is not None and med and sh < 0.5 * med) else None)
    return segs, r3(med)


# ------------------------------------------------------------------ 主流程 ---

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--submission", default=DEFAULT_SUBMISSION)
    args = ap.parse_args()

    snap, snap_sha, snap_bytes = load_snapshot()
    site_gj, roads_gj, cons_gj = load_submission(args.submission)
    fb = Fabric(snap, site_gj)

    # --- 肌理四项 ---
    r1 = reading_network_density(fb)
    adj, edges = build_graph(fb)
    r2 = reading_intersection_density(fb, adj)
    r2["graph_edges_total"] = len(edges)
    r3d, areas = reading_blocks(fb, edges)

    # --- 偏差三项 ---
    wtree, wgeoms = make_tree(fb, fb.walkable)
    ptree, pgeoms = make_tree(fb, fb.pedestrian)

    inv = Transformer.from_crs("EPSG:4326", PROJ_CRS, always_xy=True)
    proj = lambda x, y: inv.transform(x, y)

    centerlines = []
    for f in roads_gj["features"]:
        pr = f["properties"]
        ln = transform(proj, shape(f["geometry"]))
        pts = sample_line(ln, CENTERLINE_SAMPLE_INTERVAL_M)
        dw = [nearest_dist(wtree, wgeoms, p) for p in pts]
        dp = [nearest_dist(ptree, pgeoms, p) for p in pts]
        kmax = max(range(len(dw)), key=lambda k: dw[k])
        mlon, mlat = fb.unproj(pts[kmax].x, pts[kmax].y)
        centerlines.append({
            "id": pr["id"],
            "name_zh": pr.get("name_zh"),
            "name_en": pr.get("name_en"),
            "road_class": pr.get("road_class"),
            "submitted_confidence": pr.get("confidence"),
            "length_m": r3(ln.length),
            "vs_walkable_network": dist_stats(dw),
            "vs_pedestrian_dedicated": dist_stats(dp),
            "max_deviation_location": {
                "lon": round(mlon, 6),
                "lat": round(mlat, 6),
                "chainage_m": r3(kmax * CENTERLINE_SAMPLE_INTERVAL_M),
                "distance_m": r3(dw[kmax]),
            },
        })

    nodes_out = []
    for f in cons_gj["features"]:
        pr = f["properties"]
        x, y = f["geometry"]["coordinates"]
        p = Point(*proj(x, y))
        nodes_out.append({
            "id": pr["id"],
            "name_zh": pr.get("name_zh"),
            "scenario_id": pr.get("scenario_id"),
            "key_area_id": pr.get("key_area_id"),
            "submitted_confidence": pr.get("confidence"),
            "submitted_evidence_status": pr.get("evidence_status"),
            "lon": round(x, 6),
            "lat": round(y, 6),
            "in_site": fb.site.contains(p),
            "distance_to_walkable_network_m": r3(nearest_dist(wtree, wgeoms, p)),
            "distance_to_pedestrian_dedicated_m": r3(nearest_dist(ptree, pgeoms, p)),
        })

    # 过街节点索引
    node_geoms = []
    node_recs = []
    for n in fb.nodes:
        px, py = proj(n[1], n[2])
        node_geoms.append(Point(px, py))
        node_recs.append(n)
    node_tree = STRtree(node_geoms)

    crossings = collect_crossings(fb, node_tree, node_geoms, node_recs)
    crossings_with_links = collect_crossings(fb, node_tree, node_geoms, node_recs,
                                             include_links=True)
    segs, seg_median_share = segment_quality(fb)

    # --- 三条横向接口对应的既有穿越 ---
    iface_ids = ["ROAD-002", "ROAD-003", "ROAD-004"]
    interfaces = []
    for f in roads_gj["features"]:
        pr = f["properties"]
        if pr["id"] not in iface_ids:
            continue
        ln = transform(proj, shape(f["geometry"]))
        corr = ln.buffer(150.0)
        hits = []
        for c in crossings:
            cp = Point(*proj(c["lon"], c["lat"]))
            if corr.contains(cp):
                hits.append(dict(c, distance_to_interface_m=r3(ln.distance(cp))))
        # 该接口线自身与屏障的相交情况，以及走廊范围内出现的屏障要素
        bar_hits = []
        bar_near = []
        for i in sorted(fb.rail_active + fb.rail_heritage + fb.road_barrier):
            bl = fb.pline(i)
            if bl is None:
                continue
            if bl.intersects(corr):
                bar_near.append({
                    "barrier_osm_id": fb.ways[i][0],
                    "barrier_railway": fb.ways[i][2],
                    "barrier_highway": fb.ways[i][1],
                    "barrier_name": fb.ways[i][3],
                    "distance_to_interface_m": r3(ln.distance(bl)),
                })
            if ln.intersects(bl):
                ip = ln.intersection(bl)
                rp = ip if ip.geom_type == "Point" else ip.representative_point()
                blon, blat = fb.unproj(rp.x, rp.y)
                bar_hits.append({
                    "barrier_osm_id": fb.ways[i][0],
                    "barrier_railway": fb.ways[i][2],
                    "barrier_highway": fb.ways[i][1],
                    "barrier_name": fb.ways[i][3],
                    "lon": round(blon, 6),
                    "lat": round(blat, 6),
                })
        bar_near.sort(key=lambda b: (b["distance_to_interface_m"], b["barrier_osm_id"]))
        ep = sorted([h for h in hits if h["grade"] == "evidence_present"],
                    key=lambda h: h["distance_to_interface_m"])
        nr = sorted([h for h in hits if h["grade"] == "no_evidence_registered_only"],
                    key=lambda h: h["distance_to_interface_m"])
        if bar_hits:
            presence = "barrier_crossed_by_interface_line"
        elif bar_near:
            presence = "barrier_within_corridor_but_not_crossed"
        else:
            presence = "no_barrier_recorded_in_corridor"
        interfaces.append({
            "id": pr["id"],
            "name_zh": pr.get("name_zh"),
            "name_en": pr.get("name_en"),
            "submitted_confidence": pr.get("confidence"),
            "length_m": r3(ln.length),
            "search_corridor_half_width_m": 150.0,
            "barrier_presence": presence,
            "barrier_presence_note_zh": {
                "barrier_crossed_by_interface_line": "该接口线在快照中与屏障要素直接相交，横向走通须解决该屏障的穿越问题。",
                "barrier_within_corridor_but_not_crossed": "该接口线本身未与屏障相交，但走廊范围内存在屏障要素，接口两端的连接仍可能受其制约。",
                "no_barrier_recorded_in_corridor": "该接口线的 150 米走廊范围内，快照未记录任何本包定义的屏障要素（在营轨道、遗址轨道、机动车专用高等级道路主线）。因此该走向不存在跨屏障穿越问题，本项的零计数不表示该处无法横向连接。",
            }[presence],
            "barrier_presence_note_en": {
                "barrier_crossed_by_interface_line": "The interface line intersects a barrier feature in the snapshot; lateral continuity here depends on resolving that crossing.",
                "barrier_within_corridor_but_not_crossed": "The interface line itself does not intersect a barrier, but barrier features exist within the corridor and may still constrain the connections at either end.",
                "no_barrier_recorded_in_corridor": "Within the 150 metre corridor of this interface line, the snapshot records no barrier feature as defined by this package (active rail, heritage rail, motor-only high-grade road mainline). There is therefore no barrier-crossing problem on this alignment, and the zero count here does not mean the location cannot be connected laterally.",
            }[presence],
            "barriers_intersected_by_interface_line": bar_hits,
            "barriers_within_corridor": bar_near,
            "existing_crossings_evidence_present": ep,
            "existing_crossings_no_evidence_registered_only": nr,
            "evidence_present_count": len(ep),
            "no_evidence_count": len(nr),
        })

    result = build_output(fb, snap, snap_sha, snap_bytes, args.submission,
                          r1, r2, r3d, areas, centerlines, nodes_out,
                          interfaces, crossings, crossings_with_links,
                          segs, seg_median_share, wgeoms, pgeoms)

    with open(OUT, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=1, sort_keys=False)
        f.write("\n")

    print("site area km2      %.6f" % fb.site_area_km2)
    print("R1 network density %s km/km2 (len %s m)" % (r1["value"], r1["total_length_m"]))
    print("R2 intersections   %s /km2 (n=%d, merged %d)" %
          (r2["value"], r2["intersection_count"], r2["vertices_merged_by_clustering"]))
    print("R3 median block    %s m2 (n=%d)" % (r3d["median_all_m2"], r3d["block_count"]))
    print("R4 oversized share %s %% (n=%d)" % (r3d["oversized_share_pct"], r3d["oversized_count"]))
    print("crossings          %d (evidence_present %d / no_evidence %d)" %
          (len(crossings),
           len([c for c in crossings if c["grade"] == "evidence_present"]),
           len([c for c in crossings if c["grade"] == "no_evidence_registered_only"])))
    with open(OUT, "rb") as f:
        print("readings sha256    %s" % hashlib.sha256(f.read()).hexdigest())


def build_output(fb, snap, snap_sha, snap_bytes, sub,
                 r1, r2, r3d, areas, centerlines, nodes_out,
                 interfaces, crossings, crossings_with_links,
                 segs, seg_median_share, wgeoms, pgeoms):
    ep = [c for c in crossings if c["grade"] == "evidence_present"]
    nr = [c for c in crossings if c["grade"] == "no_evidence_registered_only"]

    by_kind = {}
    for c in ep:
        for k in c["evidence_kinds"]:
            by_kind[k] = by_kind.get(k, 0) + 1

    # 铁路要素在场地内的纵向覆盖范围
    rail_lat = []
    for i in fb.rail_active + fb.rail_heritage:
        ln = fb.pline(i)
        if ln is None:
            continue
        it = ln.intersection(fb.site)
        if it.is_empty:
            continue
        b = it.bounds
        lo = fb.unproj(b[0], b[1])[1]
        hi = fb.unproj(b[2], b[3])[1]
        rail_lat.append((lo, hi))
    site_lat = (fb.site_bounds_lat if hasattr(fb, "site_bounds_lat")
                else (39.939, 40.0265))
    rail_span = None
    if rail_lat:
        rlo = min(a for a, _ in rail_lat)
        rhi = max(b for _, b in rail_lat)
        rail_span = {
            "rail_lat_min": round(rlo, 6),
            "rail_lat_max": round(rhi, 6),
            "rail_lat_extent_km": r3((rhi - rlo) * 110.574),
            "site_lat_min": round(site_lat[0], 6),
            "site_lat_max": round(site_lat[1], 6),
            "site_lat_extent_km": r3((site_lat[1] - site_lat[0]) * 110.574),
            "rail_share_of_site_length_pct": r3(100.0 * (rhi - rlo) /
                                                (site_lat[1] - site_lat[0])),
        }

    # 跨轨道穿越的聚焦统计：记录数会因一处穿越由多条 way 组成而重复，
    # 因此按 50 米聚类估计物理穿越位置数。
    def rail_focus(kind, in_site_only):
        recs = [c for c in crossings
                if c["barrier_kind"] == kind and (c["in_site"] or not in_site_only)]
        pts = [fb._proj(c["lon"], c["lat"]) for c in recs]
        locs, _ = cluster_points(pts, RAIL_CROSSING_CLUSTER_RADIUS_M) if pts else (0, 0)
        return {
            "records": len(recs),
            "distinct_locations_50m_cluster": locs,
            "evidence_present_primary": len([c for c in recs if c["evidence_tier"] == "primary"]),
            "evidence_present_secondary_layer_only": len([c for c in recs if c["evidence_tier"] == "secondary"]),
            "no_evidence_registered_only": len([c for c in recs if c["grade"] == "no_evidence_registered_only"]),
            "crossing_way_osm_ids": sorted({c["crossing_way_osm_id"] for c in recs}),
        }

    rail_active_site = rail_focus("rail_active", True)
    rail_heritage_site = rail_focus("rail_heritage", True)

    sparse = [s for s in segs if s.get("flag")]
    lc_nodes = [n for n in fb.nodes if n[3] == "railway=level_crossing"]
    lc_in_site = [n for n in lc_nodes
                  if fb.site.contains(Point(*fb._proj(n[1], n[2])))]
    tactile_ways = len([w for w in fb.ways if (w[4] or {}).get("tactile_paving")])
    tactile_nodes = len([n for n in fb.nodes if (n[5] or {}).get("tactile_paving")])
    tactile = tactile_ways + tactile_nodes

    return {
        "declaration": {
            "package_zh": "万感京张 OSM 肌理读数包 —— 读数文件",
            "package_en": "Every-Sense Jingzhang OSM fabric readings -- readings file",
            "status": "PROVISIONAL",
            "statement_zh": [
                "本文件全部读数为 OpenStreetMap 快照时点的计算值，状态为 PROVISIONAL（临时）。",
                "读数不是现场测量结果，不是官方测绘或规划数据，不构成任何规划结论、设计依据或合规判定。",
                "读数只描述快照所记录的现状城市肌理，不表达关于应当建设何种设施、建设多少数量的任何主张。",
                "读数中的方法阈值（超大封闭街块 40000 平方米、交叉口聚类半径 15 米、采样间距 25 米、穿越夹角下限 30 度、过街节点检索半径 10 米）均为本包的方法选择，不是规范强制值，改变阈值将改变读数。",
                "凡与提交几何相关的偏差读数，其对象为提交包中标注为 agent_generated_design、geometry_role=design_proposal 的概念性几何；这些几何本身为示意走向，偏差数值反映概念几何与现状肌理的距离，不反映选线错误。",
                "数值登记精度：全部读数值保留三位小数；经纬度坐标保留六位小数（约 0.11 米），与快照坐标精度一致，因为坐标是位置标识而非读数值，三位小数不足以定位。登记精度不代表测量精度，OpenStreetMap 社区数据的实际定位误差远大于登记位数。",
            ],
            "statement_en": [
                "Every reading in this file is a value computed at the timestamp of the OpenStreetMap snapshot; its status is PROVISIONAL.",
